html:not([data-kami-skin]) .kami-item.is-demo { opacity: .62; cursor: default; }
html:not([data-kami-skin]) .kami-item-main { min-width: 0; }
html:not([data-kami-skin]) .kami-item-side { flex: none; margin-left: auto; color: var(--kami-fg-mute); font-size: var(--kami-fs-sm); }

html:not([data-kami-skin]) .kami-badge,
html:not([data-kami-skin]) .kami-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
