}
html:not([data-kami-skin]) .kami-chip { border-color: var(--kami-line); color: var(--kami-fg-dim); background: var(--kami-t1); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="action"]  { color: var(--kami-kind-action); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="persona"] { color: var(--kami-kind-persona); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="plot"]    { color: var(--kami-kind-plot); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="info"]    { color: var(--kami-kind-info); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="fun"]     { color: var(--kami-kind-fun); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="nsfw"]    { color: var(--kami-kind-nsfw); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="other"]   { color: var(--kami-kind-other); }

/* ---------- 折叠 ---------- */
html:not([data-kami-skin]) .kami-collapse-head { cursor: pointer; user-select: none; }
html:not([data-kami-skin]) .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * .8);
  color: var(--kami-fg-mute);
  transition: transform var(--kami-dur) var(--kami-ease), color var(--kami-dur) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev { transform: rotate(90deg); color: var(--kami-accent); }
html:not([data-kami-skin]) .kami-collapse > .kami-body { display: none; }
html:not([data-kami-skin]) .kami-collapse[data-kami-open="1"] > .kami-body {
  display: block;
  animation: kami-base-in var(--kami-dur-slow) var(--kami-ease-out) backwards;
}
@keyframes kami-base-in {
