  to { opacity: 1; transform: none; }
}

/* ---------- 正文 / markdown / 原文 ---------- */
html:not([data-kami-skin]) .kami-md {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
}
html:not([data-kami-skin]) .kami-md > :first-child { margin-top: 0; }
html:not([data-kami-skin]) .kami-md > :last-child { margin-bottom: 0; }
html:not([data-kami-skin]) .kami-md p { margin: .5em 0; }
html:not([data-kami-skin]) .kami-md h1,
html:not([data-kami-skin]) .kami-md h2,
html:not([data-kami-skin]) .kami-md h3 {
  margin: .9em 0 .4em;
