 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 1px;
  right: 3px;
  left: auto;
  z-index: 2;
  margin-left: 0;
  pointer-events: auto;
}
html:not([data-kami-skin]) .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
html:not([data-kami-skin]) .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}


/* ===== 结构层：只声明“必须存在才能工作”的最小行为，不含任何外观 ===== */
html, body { margin: 0; padding: 0; background: transparent; border: 0; }
body { font-family: inherit; color: inherit; }
.kami-root[data-kami-comp="options"] { position: relative; }
.kami-root[data-kami-comp="options"] .kami-item { appearance: none; -webkit-appearance: none; font: inherit; }
