  /* ---------- 高度自保（只保留启动期的一次性兜底）----------
   * 平台机制是主路径：酒馆助手用 ResizeObserver(body) -> frameElement.style.height = body.scrollHeight
   * 驱动消息 iframe 的高度，实测可靠（docs/真机验证备忘.md 第三节）。**这里不再自己挂观察者** ——
   * 每个聊天楼层再挂一个 ResizeObserver 只是把平台那套逐字重做一遍，白付一份开销。
   * 保留的只有启动期兜底：首帧那几次重测还没跑到时，内容已经比 iframe 高（iframe 内是 overflow:hidden，
   * 表现成「点了没反应」），所以在 0/80/260/600ms 各量一次；之后一律交给平台。
   * 量法只有一种：body.scrollHeight（documentElement.scrollHeight 至少等于视口高度，会让 iframe 只增不减）。 */
  function syncHeight() {
    try {
      var fe = window.frameElement;
      if (!fe) { return; }
      var h = Math.max(document.body.scrollHeight, 40);
      fe.style.height = h + 'px';
    } catch (e) { }
  }
  function scheduleHeightSync() {
    /* 渲染有过渡，过早测量会偏小，所以补几个时间点 */
    [0, 80, 260, 600].forEach(function (t) { setTimeout(syncHeight, t); });
  }

  /* ---------- 与酒馆交互 ---------- */
  function parentDoc() {
    try { return (window.parent && window.parent !== window && window.parent.document) ? window.parent.document : null; }
    catch (e) { return null; }
  }
  function inputEl() {
    var d = parentDoc() || document;
    return d.getElementById('send_textarea');
  }
  function fireInput(el) {
    try {
      var doc = el.ownerDocument;
      var ev = doc.createEvent('Event');
      ev.initEvent('input', true, true);
      el.dispatchEvent(ev);
    } catch (e) { }
  }
  function fillText(text) {
    var el = inputEl();
    if (!el) { return false; }
    var cur = String(el.value || '').replace(new RegExp(SP + '+$', 'g'), '');
    el.value = cur ? (cur + NL + text) : text;
    fireInput(el);
    try {
      el.focus();
      if (typeof el.selectionStart === 'number') { el.selectionStart = el.value.length; el.selectionEnd = el.value.length; }
      el.scrollTop = el.scrollHeight;
    } catch (e) { }
    return true;
  }
  function sendText(text, done) {
    /* 优先走酒馆助手：新建用户楼层 → 触发生成 */
    try {
      if (typeof createChatMessages === 'function' && typeof generate === 'function') {
        Promise.resolve(createChatMessages([{ role: 'user', message: text }]))
          .then(function () { return generate({ should_stream: true }); })
          .then(function () { done(true); }, function () { done(false); });
        return;
      }
    } catch (e) { }
    /* 兜底：填进输入框并点酒馆的发送键 */
    try {
      if (fillText(text)) {
        var d = parentDoc();
        var btn = d && (d.getElementById('send_but') || d.querySelector('#send_but'));
        if (btn) { btn.click(); done(true); return; }
      }
    } catch (e) { }
    done(false);
  }

  /* ---------- 渲染 ---------- */
  var mount = { list: null, root: null, toastEl: null, toastTimer: null, demo: false };
  function toast(msg, bad) {
    var box = mount.toastEl;
    if (!box) { return; }
    box.hidden = false;
    box.textContent = msg;
    box.classList.toggle('is-bad', !!bad);
    if (mount.toastTimer) { clearTimeout(mount.toastTimer); }
    mount.toastTimer = setTimeout(function () { box.hidden = true; }, 1700);
  }
  function markDone(btn) {
    if (!btn) { return; }
    btn.classList.add('is-done');
    setTimeout(function () { btn.classList.remove('is-done'); }, ACT_MS);
  }
  function makeCard(root, item, demo, idx) {
    var kind = KIND[item.type] || 'other';
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'kami-item kami-card' + (demo ? ' is-demo' : '');
    btn.setAttribute('data-kami-kind', kind);
    if (demo) { btn.setAttribute('aria-disabled', 'true'); }

    var head = document.createElement('span');
    head.className = 'kami-card-head';
    var badge = document.createElement('span');
    badge.className = 'kami-badge';
    badge.setAttribute('data-kami-kind', kind);
    badge.textContent = item.type === 'nsfw' ? 'NSFW' : item.type;
    var title = document.createElement('span');
    title.className = 'kami-card-title';
    title.textContent = item.title || ('选项 ' + (idx + 1));
    var side = document.createElement('span');
    side.className = 'kami-item-side';
    side.setAttribute('aria-hidden', 'true');
    side.textContent = root.getAttribute('data-kami-mode') === 'send' ? '→' : '↵';
    head.appendChild(badge); head.appendChild(title); head.appendChild(side);

    var bodyEl = document.createElement('span');
    bodyEl.className = 'kami-card-body';
    bodyEl.textContent = item.content;

    btn.appendChild(head);
    btn.appendChild(bodyEl);
    btn.addEventListener('click', function () { onPick(root, btn, item.content, demo); });
    return btn;
  }
  function onPick(root, btn, text, demo) {
    if (demo) { toast(labelVar(root, 'demo') || '示例数据不可发送', true); return; }
    var mode = root.getAttribute('data-kami-mode') === 'send' ? 'send' : 'fill';
    if (mode !== 'send') {
      if (fillText(text)) { markDone(btn); toast(labelVar(root, 'filled') || '已填入输入框'); }
      else { toast(labelVar(root, 'noinput') || '未找到酒馆输入框', true); }
      return;
    }
    if (btn.getAttribute('data-kami-busy') === '1') { return; }
    btn.setAttribute('data-kami-busy', '1');
    sendText(text, function (ok) {
      btn.removeAttribute('data-kami-busy');
      if (ok) { markDone(btn); toast(labelVar(root, 'sent') || '已发送'); }
      else { toast(labelVar(root, 'sendfail') || '发送失败，请手动发送', true); }
    });
  }
  function renderList(root, list, demo) {
    var host = q('[data-kami-role="list"]', root);
    if (!host) { return; }
    host.textContent = '';
    for (var i = 0; i < list.length; i++) { host.appendChild(makeCard(root, list[i], demo, i)); }
    var count = q('[data-kami-role="count"]', root);
    if (count) { count.textContent = demo ? (labelVar(root, 'demo') || '示例') : (list.length + ' ' + (labelVar(root, 'unit') || '项')); }
    var hint = q('[data-kami-role="hint"]', root);
    if (hint) {
      hint.textContent = demo
        ? '未检测到选项 JSON，以下为示例内容'
        : (root.getAttribute('data-kami-mode') === 'send' ? '轻点卡片直接发送' : '轻点卡片即可生效');
    }
  }
  var SAMPLE = [
    { title: '示例选项', type: '行动', content: '这里会显示模型给出的行动选项。' },
    { title: '示例选项', type: '推进', content: '把这段 JSON 交给正则替换即可渲染成可点击卡片。' }
  ];

  /* ---------- 启动 ---------- */
  function boot() {
    var root = q('.kami-root[data-kami-comp="options"]');
    if (!root || root.getAttribute('data-kami-ready') === '1') { return; }
    root.setAttribute('data-kami-ready', '1');
    mount.root = root;
    mount.toastEl = q('.kami-toast', root);

    var raw = payload();
    var list = raw ? parseList(raw) : null;
    mount.demo = !list;
    renderList(root, list || SAMPLE, mount.demo);

    var mode = store(LS_MODE) === 'send' ? 'send' : 'fill';
    function setMode(m, silent) {
      mode = m === 'send' ? 'send' : 'fill';
      root.setAttribute('data-kami-mode', mode);
      qa('.kami-seg-item', root).forEach(function (b) {
        b.classList.toggle('is-on', b.getAttribute('data-kami-mode') === mode);
      });
      qa('.kami-item-side', root).forEach(function (s) { s.textContent = mode === 'send' ? '→' : '↵'; });
      applyLabels(root);
      if (!silent) { store(LS_MODE, mode); }
    }
    qa('.kami-seg-item', root).forEach(function (b) {
      b.addEventListener('click', function (ev) { ev.stopPropagation(); setMode(b.getAttribute('data-kami-mode')); });
    });
    setMode(mode, true);

    try {
      var mo = new MutationObserver(function () { applyLabels(root); });
      mo.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['data-kami-skin', 'data-kami-scheme', 'data-kami-density', 'data-kami-motion']
      });
    } catch (e) { }
    applyLabels(root);
    scheduleHeightSync();
  }

  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', boot); } else { boot(); }
  window.addEventListener('load', function () { try { boot(); } catch (e) { } });
})();
</script>
</body>
</html>

